package tech.wenisch.smtp2x.config;
import java.util.*; import org.springframework.security.core.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.oauth2.client.oidc.userinfo.OidcUserRequest; import org.springframework.security.oauth2.client.userinfo.OAuth2UserService; import org.springframework.security.oauth2.core.oidc.user.*; import org.springframework.security.oauth2.core.oidc.OidcUserInfo; import org.springframework.security.oauth2.core.user.OAuth2UserAuthority; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import tech.wenisch.smtp2x.domain.*; import tech.wenisch.smtp2x.repository.AppUserRepository; import tech.wenisch.smtp2x.service.AuditService;
@Service public class OidcUserService implements OAuth2UserService<OidcUserRequest,OidcUser>{private final AppUserRepository users;private final Smtp2xProperties properties;private final AuditService audit;public OidcUserService(AppUserRepository u,Smtp2xProperties p,AuditService a){users=u;properties=p;audit=a;}@Transactional public OidcUser loadUser(OidcUserRequest req){Map<String,Object> claims=new LinkedHashMap<>(req.getIdToken().getClaims());String value=string(claims,"email");if(value==null)value=string(claims,"preferred_username");if(value==null)throw new IllegalArgumentException("OIDC token requires email or preferred_username");final String identity=value;AppUser user=users.findByEmailIgnoreCase(identity).orElseGet(()->new AppUser(identity,"{noop}oidc",UserRole.PENDING,false,true));if(properties.security().oidc().roleMappingEnabled())user.role(mappedRole(claims));users.save(user);audit.record(identity,"OIDC_LOGIN","user",user.getId().toString(),"role="+user.getRole());claims.put("email",identity);Set<GrantedAuthority> authorities=new LinkedHashSet<>();authorities.add(new OAuth2UserAuthority(claims));authorities.add(new SimpleGrantedAuthority("ROLE_"+user.getRole()));return new DefaultOidcUser(authorities,req.getIdToken(),new OidcUserInfo(claims),"email");}private UserRole mappedRole(Map<String,Object> c){Set<String> r=new HashSet<>();add(r,c.get("roles"));if(c.get("realm_access")instanceof Map<?,?>m)add(r,m.get("roles"));if(c.get("resource_access")instanceof Map<?,?>m)m.values().forEach(v->{if(v instanceof Map<?,?>x)add(r,x.get("roles"));});return r.stream().anyMatch("SMTP2X_Admin"::equalsIgnoreCase)?UserRole.ADMIN:r.stream().anyMatch("SMTP2X_Viewer"::equalsIgnoreCase)?UserRole.VIEWER:UserRole.PENDING;}private void add(Set<String>s,Object value){if(value instanceof Collection<?> c)c.stream().filter(String.class::isInstance).map(String.class::cast).forEach(s::add);}private String string(Map<String,Object> c,String key){Object v=c.get(key);return v instanceof String s&&!s.isBlank()?s.trim():null;}}
